def api_matters(request):
    user = _api_user(request)
    if not user:
        return JsonResponse({"error": "valid X-API-Key header required"}, status=401)
    data = [
        {
            "id": matter.id,
            "title": matter.title,
            "client": matter.client.name,
            "status": matter.status,
            "practice_area": matter.practice_area.name,
            "target_resolution_date": matter.target_resolution_date.isoformat() if matter.target_resolution_date else None,
        }
        for matter in matter_queryset_for(user)[:100]
    ]
    return JsonResponse({"matters": data})

def api_matter_documents(request, pk):
    user = _api_user(request)
    if not user:
        return JsonResponse({"error": "valid X-API-Key header required"}, status=401)
    matter = get_object_or_404(matter_queryset_for(user), pk=pk)
    documents = document_queryset_for(user).filter(matter=matter)
    data = [
        {
            "id": doc.id,
            "title": doc.title,
            "category": doc.category,
            "visibility": doc.visibility,
            "versions": doc.versions.count(),
        }
        for doc in documents
    ]
    return JsonResponse({"matter": matter.id, "documents": data})

